#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {}

    void eat(int fish) {
        this->fish = this->fish + fish;
    }
};

int main() {
    int a = 0;
    int b = 0;
    cin >> a >> b;

    Cat c1("{name}", a);
    c1.eat(b);
    cout << c1.name << " 现在有 " << c1.fish << " 条" << endl;
    return 0;
}
